'use strict';

const { createApplicationInterfaceCapability } = require('./builtin/uip-tools');

const HARNESS_REFERENCE = Object.freeze({ kind: 'harness', id: 'application-interface' });

function normalizedScopeId(scopeId) {
    return String(scopeId || 'default');
}

function hasApplicationInterfaceTargets(uipService, scopeId = 'default') {
    if (!uipService || typeof uipService.listTargets !== 'function') return false;
    try {
        const targets = uipService.listTargets({ scopeId: normalizedScopeId(scopeId) });
        return Array.isArray(targets) && targets.length > 0;
    } catch (_) {
        return false;
    }
}

function stripLegacyApplicationInterfaceProviders(references) {
    return (Array.isArray(references) ? references : []).filter((reference) => !(
        String(reference?.kind || 'python').toLowerCase() === 'builtin'
        && String(reference?.id || '').toLowerCase() === 'uip'
    ));
}

function registerApplicationInterfaceHarness(uipService, scopeId, register) {
    if (!hasApplicationInterfaceTargets(uipService, scopeId)) return false;
    const capability = createApplicationInterfaceCapability(uipService, { scopeId: normalizedScopeId(scopeId) });
    for (const entry of capability.tools) register(entry.definition, entry.execute, HARNESS_REFERENCE);
    return true;
}

module.exports = {
    hasApplicationInterfaceTargets,
    registerApplicationInterfaceHarness,
    stripLegacyApplicationInterfaceProviders,
};
