'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { portablePath } = require('../../filesystem/path-utils');

const MAX_READ_LINES = 5_000;
const MAX_SEARCH_RESULTS = 1_000;
const MAX_TEXT_FILE_BYTES = 10 * 1024 * 1024;

function definition(name, description, parameters) {
    return { type: 'function', function: { name, description, parameters } };
}

const FILE_TOOL_DEFINITIONS = Object.freeze([
    definition('read_file', 'Read a UTF-8 text file inside the selected workspace.', {
        type: 'object',
        properties: {
            path: { type: 'string', minLength: 1, description: 'Workspace-relative file path.' },
            offset: { type: 'integer', minimum: 1, description: 'First 1-based line to return.' },
            limit: { type: 'integer', minimum: 1, maximum: MAX_READ_LINES, description: 'Maximum number of lines.' },
        },
        required: ['path'],
        additionalProperties: false,
    }),
    definition('write_file', 'Write a UTF-8 text file inside the selected workspace, creating parent directories when needed.', {
        type: 'object',
        properties: {
            path: { type: 'string', minLength: 1, description: 'Workspace-relative file path.' },
            content: { type: 'string', description: 'Complete file contents.' },
        },
        required: ['path', 'content'],
        additionalProperties: false,
    }),
    definition('patch', 'Replace one exact string in a UTF-8 workspace file.', {
        type: 'object',
        properties: {
            path: { type: 'string', minLength: 1, description: 'Workspace-relative file path.' },
            old_string: { type: 'string', minLength: 1, description: 'Exact text to replace.' },
            new_string: { type: 'string', description: 'Replacement text.' },
        },
        required: ['path', 'old_string', 'new_string'],
        additionalProperties: false,
    }),
    definition('search_files', 'Search UTF-8 files inside the selected workspace for a literal text pattern.', {
        type: 'object',
        properties: {
            pattern: { type: 'string', minLength: 1, description: 'Literal text to find.' },
            file_glob: { type: 'string', description: 'Optional workspace-relative glob, such as **/*.md.' },
        },
        required: ['pattern'],
        additionalProperties: false,
    }),
]);

function globToRegExp(glob) {
    const source = portablePath(glob || '**/*');
    let pattern = '^';
    for (let index = 0; index < source.length; index += 1) {
        const character = source[index];
        const next = source[index + 1];
        if (character === '*' && next === '*') {
            index += 1;
            if (source[index + 1] === '/') {
                index += 1;
                pattern += '(?:.*/)?';
            } else pattern += '.*';
        } else if (character === '*') pattern += '[^/]*';
        else if (character === '?') pattern += '[^/]';
        else pattern += character.replace(/[|\\{}()[\]^$+?.]/gu, '\\$&');
    }
    return new RegExp(`${pattern}$`, process.platform === 'win32' ? 'iu' : 'u');
}

async function readUtf8(filePath) {
    const stat = await fs.promises.stat(filePath);
    if (!stat.isFile()) throw new Error('Requested workspace path is not a file.');
    if (stat.size > MAX_TEXT_FILE_BYTES) throw new Error('Workspace text files are limited to 10 MiB.');
    const buffer = await fs.promises.readFile(filePath);
    if (buffer.includes(0)) throw new Error('Requested file appears to be binary.');
    return buffer.toString('utf8');
}

async function walkFiles(rootPath, directoryPath = rootPath, output = []) {
    const entries = await fs.promises.readdir(directoryPath, { withFileTypes: true });
    entries.sort((left, right) => left.name.localeCompare(right.name));
    for (const entry of entries) {
        if (entry.isSymbolicLink()) continue;
        const absolutePath = path.join(directoryPath, entry.name);
        if (entry.isDirectory()) await walkFiles(rootPath, absolutePath, output);
        else if (entry.isFile()) output.push(absolutePath);
    }
    return output;
}

function createFileToolProvider(workspace, options = {}) {
    if (!workspace) throw new Error('WorkspaceService is required for file tools.');
    const filesystemAccess = options.filesystemAccess || null;
    const workspaceRoot = async () => {
        const value = typeof workspace.getRoot === 'function' ? await workspace.getRoot() : workspace.rootPath;
        return value?.path || value || workspace.rootPath || '';
    };
    const resolvePath = async (rawPath, resolveOptions = {}) => filesystemAccess
        ? filesystemAccess.resolvePath(rawPath, await workspaceRoot(), resolveOptions)
        : workspace.resolvePath(rawPath, resolveOptions);
    const byName = new Map(FILE_TOOL_DEFINITIONS.map((item) => [item.function.name, item]));
    const handlers = new Map();

    handlers.set('read_file', async (args) => {
        const filePath = await resolvePath(args.path);
        const content = await readUtf8(filePath);
        const lines = content.split(/\r?\n/u);
        const offset = Math.max(1, Number(args.offset) || 1);
        const limit = Math.min(MAX_READ_LINES, Math.max(1, Number(args.limit) || 500));
        return lines.slice(offset - 1, offset - 1 + limit)
            .map((line, index) => `${offset + index} | ${line}`)
            .join('\n');
    });

    handlers.set('write_file', async (args) => {
        const filePath = await resolvePath(args.path, { allowMissing: true });
        await fs.promises.mkdir(path.dirname(filePath), { recursive: true });
        await fs.promises.writeFile(filePath, String(args.content), 'utf8');
        return { path: args.path, bytes: Buffer.byteLength(String(args.content), 'utf8') };
    });

    handlers.set('patch', async (args) => {
        const filePath = await resolvePath(args.path);
        const content = await readUtf8(filePath);
        const oldText = String(args.old_string);
        const first = content.indexOf(oldText);
        if (first < 0) throw new Error('The exact old_string was not found.');
        if (content.indexOf(oldText, first + oldText.length) >= 0) throw new Error('old_string occurs more than once; provide a more specific patch.');
        const updated = `${content.slice(0, first)}${String(args.new_string)}${content.slice(first + oldText.length)}`;
        await fs.promises.writeFile(filePath, updated, 'utf8');
        return { path: args.path, replacements: 1 };
    });

    handlers.set('search_files', async (args) => {
        const root = workspace.requireRoot();
        const matcher = globToRegExp(args.file_glob || '**/*');
        const files = await walkFiles(root);
        const results = [];
        for (const filePath of files) {
            const relative = portablePath(path.relative(root, filePath));
            if (!matcher.test(relative)) continue;
            let content;
            try { content = await readUtf8(filePath); } catch (_) { continue; }
            content.split(/\r?\n/u).forEach((line, index) => {
                if (results.length >= MAX_SEARCH_RESULTS || !line.includes(args.pattern)) return;
                results.push(`${relative}:${index + 1}: ${line}`);
            });
            if (results.length >= MAX_SEARCH_RESULTS) break;
        }
        return results.length ? results.join('\n') : 'No matches found.';
    });

    return {
        id: 'file',
        name: 'Workspace File Tools',
        tools: FILE_TOOL_DEFINITIONS.map((tool) => ({ definition: tool, execute: handlers.get(tool.function.name) })),
        definitions: byName,
    };
}

module.exports = {
    FILE_TOOL_DEFINITIONS,
    MAX_READ_LINES,
    MAX_SEARCH_RESULTS,
    createFileToolProvider,
    globToRegExp,
};
