    const credential = resolveApiKey(config, resolved);
    if (requiresOfficialKey(resolved) && !credential.key) {
        throw new Error(`An API key is required for ${resolved.providerLabel}. Enter a session key or configure an API-key environment variable.`);
    }
    const requestBody = resolved.protocol === 'anthropic-messages'
        ? anthropicRequestBody(descriptor, body, sampler)
        : openAiRequestBody(resolved, descriptor, body, sampler);
    const url = endpoint(resolved, resolved.protocol === 'anthropic-messages' ? 'messages' : 'chat/completions');
    const response = await fetch(url, {
        method: 'POST',
        headers: authHeaders(resolved, credential.key),
        body: JSON.stringify(requestBody),
        signal,
    });
    if (!response.ok) throw await responseError(response, `${resolved.providerLabel} completion`);
    return resolved.protocol === 'anthropic-messages'
        ? streamAnthropic(response, handlers)
        : streamOpenAi(response, handlers);
