'use strict';

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..', '..');
const outputPath = path.join(root, 'BUILD_MANIFEST_SHA256.txt');
const ignoredDirectories = new Set(['.git', '.darkstar', '.blacksun', 'node_modules', 'dist', 'release', 'out', '__pycache__', 'venv', 'Diagnostics']);
